{noformat}USE taxify_rental_order_easteurope;
DROP PROCEDURE IF EXISTS update_in_loop_easteurope_7791;

DELIMITER $$
CREATE PROCEDURE update_in_loop_easteurope_7791()
BEGIN

  DECLARE v_min_id, v_max_id BIGINT;
  DECLARE v_batch_size INT DEFAULT 500;

  DECLARE v_sleep_cnt INT DEFAULT 0;
  DECLARE v_sleep_after INT DEFAULT 500;
  DECLARE v_sleep_time INT DEFAULT 6;

  SELECT 226319003, MAX(id) INTO v_min_id, v_max_id FROM taxify_rental_order_easteurope.vehicle_state_event;
  SELECT v_min_id, v_max_id, v_batch_size;

  WHILE v_min_id <= v_max_id DO
    UPDATE taxify_rental_order_easteurope.vehicle_state_event as dst
    INNER JOIN taxify_rental_order_easteurope.vehicle_state as src ON dst.vehicle_id = src.id
    SET dst.city_id = src.city_id
    WHERE dst.city_id IS NULL
    AND dst.id >= v_min_id AND dst.id < v_min_id + v_batch_size; 

    SET v_min_id = v_min_id + v_batch_size;

    SET v_sleep_cnt = v_sleep_cnt + 1;
    SELECT v_min_id, v_max_id, 100*v_min_id/v_max_id AS completed, v_sleep_cnt, v_sleep_after;

    IF v_sleep_cnt > v_sleep_after THEN
      SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
      SELECT SLEEP(v_sleep_time);
      SET v_sleep_cnt = 0;
    END IF;

  END WHILE;
END;
$$
DELIMITER ;{noformat}

