DELIMITER $$
CREATE PROCEDURE delete_in_loop()
BEGIN

    DECLARE v_min_id, v_max_id BIGINT;
    DECLARE v_batch_size INT DEFAULT 1000;
    DECLARE v_sleep_cnt INT DEFAULT 0;
    DECLARE v_sleep_after INT DEFAULT 500;
    DECLARE v_sleep_time INT DEFAULT 7;

    SELECT MIN(id), 600000000 INTO v_min_id, v_max_id FROM `taxify_pricing_order`.`final`;
    SELECT v_min_id, v_max_id, v_batch_size; 

    WHILE v_min_id <= v_max_id DO

        DELETE FROM `taxify_pricing_order`.`final` WHERE id >= v_min_id AND id < v_min_id + v_batch_size AND id < 600000000;

        SET v_min_id = v_min_id + v_batch_size;

        SET v_sleep_cnt = v_sleep_cnt + 1;
        SELECT v_min_id, v_sleep_cnt, v_sleep_after;

        IF v_sleep_cnt > v_sleep_after THEN
            SELECT CONCAT('Sleeping ', v_sleep_time, ' sec');
            SELECT SLEEP(v_sleep_time);
            SET v_sleep_cnt = 0;
        END IF;

    END WHILE;

END;
$$
DELIMITER ;

